window.__finlexDocLoaded(10148,{"id":10148,"articles":[{"id":1000637,"no":"Overview","heading":"Scope & Key Topics Covered (2026 Edition)","text":"KPMG's Insights into IFRS: An Overview (September 2026 edition) is designed for companies with a year-end of 31 December 2026. It summarises key recognition, measurement, presentation and disclosure requirements across the Conceptual Framework, IAS 1 / forthcoming IFRS 18 & IFRS 19, consolidation (IFRS 10/11/12/IAS 27/28), fair value measurement (IFRS 13), financial instruments (IFRS 9/IAS 32/IFRS 7), revenue (IFRS 15), leases (IFRS 16), and impairment (IAS 36).","seq":0},{"id":1000638,"no":"Public Links","heading":"Verified Public Resources & Handbooks","text":"Insights into IFRS — An Overview (Sept 2026 Open PDF): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf\nKPMG IFRS Accounting Toolkit (Handbooks for IFRS 2, IFRS 15, IFRS 16, IAS 33, Fair Value, IFRS 18, IFRS vs US GAAP & 2026 Illustrative Disclosures): https://kpmg.com/xx/en/what-we-do/services/audit/corporate-reporting-institute/ifrs/toolkit.html\nKPMG Global IFRS Hub: https://kpmg.com/xx/en/what-we-do/services/audit/corporate-reporting-institute/ifrs.html","seq":1}]});
